using System;using System.IO;using System.Linq;using Newtonsoft.Json.Linq;using UnityEngine;using UnityEngine.Rendering;
[DefaultExecutionOrder(11000)]public sealed class ParkingLightingStateProbe:MonoBehaviour {
 int frames;
 void LateUpdate(){if(frames>=120||FindObjectsOfType<MeshRenderer>().Length==0)return;if(++frames!=1&&frames!=120)return;var args=Environment.GetCommandLineArgs();int index=Array.IndexOf(args,"--lighting-state-output");if(index<0)return;var sh=new JArray();for(int c=0;c<3;c++)for(int i=0;i<9;i++)sh.Add(RenderSettings.ambientProbe[c,i]);var texture=ReflectionProbe.defaultTexture;
 var renderers=new JArray(FindObjectsOfType<MeshRenderer>().Select(r=>(JToken)new JObject{["name"]=r.name,["lightmap"]=r.lightmapIndex,["materials"]=new JArray(r.sharedMaterials.Select(m=>(JToken)new JObject{["shader"]=m.shader.name,["keywords"]=new JArray(m.shaderKeywords)}))}));
 var report=new JObject{["ambient_mode"]=RenderSettings.ambientMode.ToString(),["ambient"]=new JArray(RenderSettings.ambientLight.r,RenderSettings.ambientLight.g,RenderSettings.ambientLight.b),["sh"]=sh,["skybox"]=RenderSettings.skybox?RenderSettings.skybox.name:null,["reflection_mode"]=RenderSettings.defaultReflectionMode.ToString(),["reflection_intensity"]=RenderSettings.reflectionIntensity,["reflection_texture"]=texture?texture.name:null,["reflection_size"]=texture?texture.width:0,["reflection_hdr"]=new JArray(ReflectionProbe.defaultTextureHDRDecodeValues.x,ReflectionProbe.defaultTextureHDRDecodeValues.y,ReflectionProbe.defaultTextureHDRDecodeValues.z,ReflectionProbe.defaultTextureHDRDecodeValues.w),["lightmap_mode"]=LightmapSettings.lightmapsMode.ToString(),["renderers"]=renderers};File.WriteAllText(args[index+1],report.ToString());
 report["light_probe_count"]=LightmapSettings.lightProbes?LightmapSettings.lightProbes.count:0;
 report["lights"]=new JArray(FindObjectsOfType<Light>().Select(l=>(JToken)new JObject{["name"]=l.name,["type"]=l.type.ToString(),["intensity"]=l.intensity,["range"]=l.range,["position"]=new JArray(l.transform.position.x,l.transform.position.y,l.transform.position.z),["baked"]=l.bakingOutput.isBaked,["bake_type"]=l.bakingOutput.lightmapBakeType.ToString(),["render_mode"]=l.renderMode.ToString()}));File.WriteAllText(args[index+1],report.ToString());
 }
}
